function unpackRLE(rleStr) {
    const grid = [];
    const parts = rleStr.split(',');
    for (let part of parts) {
        const [valStr, countStr] = part.split('x');
        const val = parseInt(valStr);
        const count = parseInt(countStr);
        for (let i = 0; i < count; i++) {
            grid.push(val);
        }
    }
    return grid;
}

function applyGolfHoleGridFixes() {
    const idx = minigameState.golf.currentHoleIdx;
    const grid = minigameState.golf.grid;
    if (idx === 1) { // Z-Time
        // Remove three short horizontal barriers
        const barriers = [
            { x1: 720, y1: 205, x2: 875, y2: 232 },
            { x1: 457, y1: 935, x2: 599, y2: 962 },
            { x1: 530, y1: 550, x2: 668, y2: 575 }
        ];
        barriers.forEach(b => {
            const bx1 = Math.floor(b.x1 / 6), bx2 = Math.floor(b.x2 / 6);
            const by1 = Math.floor(b.y1 / 6), by2 = Math.floor(b.y2 / 6);
            for (let y = by1; y <= by2; y++) {
                for (let x = bx1; x <= bx2; x++) {
                    const cellIdx = y * 209 + x;
                    if (grid[cellIdx] === 1) {
                        grid[cellIdx] = 0; // grass
                    }
                }
            }
        });
    } else if (idx === 3) { // Unholy Asterisk
        // Add a circular obstacle of radius 42 at (629, 625)
        const cx = 629, cy = 625, radius = 42;
        for (let by = 0; by < 209; by++) {
            for (let bx = 0; bx < 209; bx++) {
                const sx = bx * 6 + 3;
                const sy = by * 6 + 3;
                if (Math.hypot(sx - cx, sy - cy) <= radius) {
                    grid[by * 209 + bx] = 1; // wall obstacle
                }
            }
        }
    } else if (idx === 4) { // O NOOOO (Hole 5)
        // Clear the southwest gray rock formation (x: 360..480, y: 900..1010)
        const bx1 = Math.floor(360 / 6), bx2 = Math.floor(480 / 6);
        const by1 = Math.floor(900 / 6), by2 = Math.floor(1010 / 6);
        for (let y = by1; y <= by2; y++) {
            for (let x = bx1; x <= bx2; x++) {
                const cellIdx = y * 209 + x;
                if (grid[cellIdx] === 1) {
                    grid[cellIdx] = 0;
                }
            }
        }
    }
}

function initGolfGame() {
    const hole = GOLF_HOLES_DATA[0];
    minigameState.golf = {
        currentHoleIdx: 0,
        stroke: 1,
        state: 'aiming', // 'aiming', 'power_windup', 'moving', 'hole_in', 'water_reset'
        ball: {
            x: hole.startX,
            y: hole.startY,
            vx: 0,
            vy: 0
        },
        aimAngle: Math.atan2(hole.holeY - hole.startY, hole.holeX - hole.startX),
        isDragging: false,
        power: 0,
        powerDirection: 1, // 1 for filling, -1 for depleting
        powerSpeed: 0.015,
        grid: unpackRLE(hole.gridRLE),
        prevBallPos: { x: hole.startX, y: hole.startY },
        animTimer: 0
    };
    applyGolfHoleGridFixes();
}

function getGridVal(x, y) {
    const bx = Math.floor(x / 6);
    const by = Math.floor(y / 6);
    if (bx < 0 || bx >= 209 || by < 0 || by >= 209) return 1; // wall out of bounds
    return minigameState.golf.grid[by * 209 + bx];
}

function isWallAt(x, y) {
    const radius = 6;
    if (getGridVal(x, y) === 1) return true;
    if (getGridVal(x - radius, y) === 1) return true;
    if (getGridVal(x + radius, y) === 1) return true;
    if (getGridVal(x, y - radius) === 1) return true;
    if (getGridVal(x, y + radius) === 1) return true;
    return false;
}

function isWaterAt(x, y) {
    return getGridVal(x, y) === 2;
}

function getElevationAt(x, y) {
    return getGridVal(x, y);
}

function nextGolfHole() {
    minigameState.golf.currentHoleIdx++;
    if (minigameState.golf.currentHoleIdx >= GOLF_HOLES_DATA.length) {
        minigameState.golf.currentHoleIdx = 0;
    }
    const hole = GOLF_HOLES_DATA[minigameState.golf.currentHoleIdx];
    minigameState.golf.stroke = 1;
    minigameState.golf.ball.x = hole.startX;
    minigameState.golf.ball.y = hole.startY;
    minigameState.golf.ball.vx = 0;
    minigameState.golf.ball.vy = 0;
    minigameState.golf.prevBallPos.x = hole.startX;
    minigameState.golf.prevBallPos.y = hole.startY;
    minigameState.golf.grid = unpackRLE(hole.gridRLE);
    applyGolfHoleGridFixes();
    minigameState.golf.aimAngle = Math.atan2(hole.holeY - hole.startY, hole.holeX - hole.startX);
    minigameState.golf.state = 'aiming';
    minigameState.golf.power = 0;
}

function updateGolfPhysics() {
    const ball = minigameState.golf.ball;
    const hole = GOLF_HOLES_DATA[minigameState.golf.currentHoleIdx];
    
    // Decelerate (higher friction in sand traps)
    const friction = (getGridVal(ball.x, ball.y) === 5) ? 0.92 : 0.98;
    ball.vx *= friction;
    ball.vy *= friction;
    
    const speed = Math.hypot(ball.vx, ball.vy);
    if (speed < 0.1) {
        ball.vx = 0;
        ball.vy = 0;
        
        minigameState.golf.power = 0;
        
        if (minigameState.golf.stroke === 3) {
            minigameState.golf.state = 'failure_screen';
            minigameState.golf.animTimer = 0;
        } else {
            minigameState.golf.state = 'aiming';
            minigameState.golf.stroke++;
            // Save this position as the starting position for the next stroke
            minigameState.golf.prevBallPos.x = ball.x;
            minigameState.golf.prevBallPos.y = ball.y;
        }
        return;
    }
    
    const steps = Math.ceil(speed);
    let dropped = false;
    
    for (let step = 0; step < steps; step++) {
        let stepVx = ball.vx / steps;
        let stepVy = ball.vy / steps;
        
        const prevElevation = getElevationAt(ball.x, ball.y);
        
        // Try X movement
        let nextX = ball.x + stepVx;
        if (isWallAt(nextX, ball.y)) {
            ball.vx = -ball.vx * 0.6;
            stepVx = -stepVx * 0.6;
        } else {
            ball.x = nextX;
        }
        
        // Try Y movement
        let nextY = ball.y + stepVy;
        if (isWallAt(ball.x, nextY)) {
            ball.vy = -ball.vy * 0.6;
            stepVy = -stepVy * 0.6;
        } else {
            ball.y = nextY;
        }
        
        // Check elevation change (3 = high, 4 = low)
        const currElevation = getElevationAt(ball.x, ball.y);
        if (prevElevation === 3 && currElevation === 4 && !dropped) {
            dropped = true;
            audio.playSFX('thunk');
            ball.vx *= 1.5;
            ball.vy *= 1.5;
        }
        
        // Check water hazard (2 = orange)
        if (isWaterAt(ball.x, ball.y)) {
            audio.playSFX('splash');
            minigameState.golf.state = 'water_reset';
            minigameState.golf.animTimer = 0;
            return;
        }
        
        // Check hole entry
        const distToHole = Math.hypot(ball.x - hole.holeX, ball.y - hole.holeY);
        if (distToHole < 20) {
            const currentSpeed = Math.hypot(ball.vx, ball.vy);
            if (currentSpeed <= 5.0) {
                audio.playSFX('clunk');
                audio.playSFX('applause');
                minigameState.golf.state = 'hole_in';
                minigameState.golf.animTimer = 0;
                ball.vx = 0;
                ball.vy = 0;
                return;
            } else {
                // Deflect
                const angle = Math.atan2(ball.vy, ball.vx);
                const diversion = (Math.random() * 30 - 15) * Math.PI / 180;
                ball.vx = Math.cos(angle + diversion) * currentSpeed;
                ball.vy = Math.sin(angle + diversion) * currentSpeed;
            }
        }
    }
}

function drawGolfGame() {
    const golf = minigameState.golf;
    if (!golf) return;
    
    // Clear background
    ctx.fillStyle = COLORS.BLACK;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    
    const greenX = isMobileMode ? Math.floor((canvas.width - 400) / 2) : 200;
    const greenY = isMobileMode ? 220 : 130;

    // Draw the green
    const hole = GOLF_HOLES_DATA[golf.currentHoleIdx];
    const greenImg = golfGreenImgs[golf.currentHoleIdx + 1];
    if (greenImg.complete && greenImg.naturalWidth > 0) {
        ctx.drawImage(greenImg, greenX, greenY, 400, 400);
    } else {
        ctx.fillStyle = '#2e5c1e';
        ctx.fillRect(greenX, greenY, 400, 400);
    }
    
    // Update movement if in moving state
    if (golf.state === 'moving') {
        updateGolfPhysics();
    }
    
    // Screen coordinates of the ball
    const bx = greenX + (golf.ball.x / 1254) * 400;
    const by = greenY + (golf.ball.y / 1254) * 400;
    
    // Draw ball
    ctx.fillStyle = COLORS.WHITE;
    ctx.beginPath();
    let radius = 4;
    if (golf.state === 'hole_in') {
        radius = Math.max(0, 4 * (1 - golf.animTimer / 60));
    }
    ctx.arc(bx, by, radius, 0, Math.PI * 2);
    ctx.fill();
    
    // Draw aiming arrow
    if (golf.state === 'aiming' || golf.state === 'power_windup') {
        const aimAngle = golf.aimAngle;
        const arrowDist = 15;
        const arrowLength = 25;
        
        const startX = bx + Math.cos(aimAngle) * arrowDist;
        const startY = by + Math.sin(aimAngle) * arrowDist;
        const endX = startX + Math.cos(aimAngle) * arrowLength;
        const endY = startY + Math.sin(aimAngle) * arrowLength;
        
        ctx.strokeStyle = COLORS.WHITE;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();
        
        const headlen = 8;
        ctx.fillStyle = COLORS.WHITE;
        ctx.beginPath();
        ctx.moveTo(endX, endY);
        ctx.lineTo(endX - headlen * Math.cos(aimAngle - Math.PI / 6), endY - headlen * Math.sin(aimAngle - Math.PI / 6));
        ctx.lineTo(endX - headlen * Math.cos(aimAngle + Math.PI / 6), endY - headlen * Math.sin(aimAngle + Math.PI / 6));
        ctx.fill();
    }
    
    // Draw hole labels
    ctx.fillStyle = COLORS.WHITE;
    ctx.font = isMobileMode ? '10px "Press Start 2P"' : '12px "Press Start 2P"';
    ctx.textAlign = 'center';
    ctx.fillText(`Hole #${hole.number}: ${hole.name}`, canvas.width / 2, isMobileMode ? 80 : 65);
    
    ctx.textAlign = 'left';
    ctx.fillText(`Stroke #${golf.stroke}`, isMobileMode ? 400 : 480, 30);
    
    // Draw power bar
    if (golf.state === 'power_windup') {
        golf.power += golf.powerSpeed * golf.powerDirection * (0.3 + 2.7 * golf.power);
        if (golf.power >= 1) {
            golf.power = 1;
            golf.powerDirection = -1;
        } else if (golf.power <= 0) {
            golf.power = 0;
            golf.powerDirection = 1;
        }
    }
    
    const barX = isMobileMode ? 180 : 280;
    const barY = isMobileMode ? 150 : 105;
    ctx.strokeStyle = COLORS.WHITE;
    ctx.lineWidth = 2;
    ctx.strokeRect(barX, barY, 240, 15);
    
    ctx.fillStyle = COLORS.WHITE;
    ctx.font = '10px "Press Start 2P"';
    ctx.textAlign = 'center';
    ctx.fillText("POWER", barX + 120, barY - 10);
    
    if (golf.power > 0) {
        const grad = ctx.createLinearGradient(barX, 0, barX + 240, 0);
        grad.addColorStop(0, '#0000FF');
        grad.addColorStop(1, '#FF0000');
        ctx.fillStyle = grad;
        ctx.fillRect(barX, barY, 240 * golf.power, 15);
    }
    
    // Draw instructions & touch buttons
    ctx.fillStyle = COLORS.WHITE;
    ctx.font = '8px "Press Start 2P"';
    ctx.textAlign = 'center';
    const prompt = isMobileMode ? "Drag to aim. Tap SWING to start wind-up and hit." : "Click & drag to aim; SPACE to start wind-up, SPACE again to hit.";
    ctx.fillText(prompt, canvas.width / 2, isMobileMode ? 645 : 545);
    
    if (isMobileMode) {
        drawTouchButton(180, 675, 240, 85, 'SWING / HIT', { bgColor: '#004400', font: '14px "Press Start 2P"' });
    }
    
    // Success / Water Hazard text indicators
    if (golf.state === 'hole_in') {
        ctx.font = '24px "Press Start 2P"';
        ctx.textAlign = 'center';
        // Faint drop shadow
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillText("SUCCESS!", 402, 302);
        
        ctx.fillStyle = COLORS.GREEN;
        ctx.fillText("SUCCESS!", 400, 300);
        
        golf.animTimer++;
        if (golf.animTimer >= 60) {
            success();
            if (minigameState.successes < 4) {
                nextGolfHole();
            }
        }
    } else if (golf.state === 'failure_screen') {
        ctx.font = '24px "Press Start 2P"';
        ctx.textAlign = 'center';
        // Faint drop shadow
        ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
        ctx.fillText("FAILURE!", 402, 302);
        
        ctx.fillStyle = COLORS.RED;
        ctx.fillText("FAILURE!", 400, 300);
        
        golf.animTimer++;
        if (golf.animTimer >= 60) {
            failure();
            if (minigameState.failures < 3) {
                nextGolfHole();
            }
        }
    } else if (golf.state === 'water_reset') {
        ctx.fillStyle = COLORS.RED;
        ctx.font = '24px "Press Start 2P"';
        ctx.textAlign = 'center';
        ctx.fillText("WATER HAZARD!", 400, 300);
        
        golf.animTimer++;
        if (golf.animTimer >= 60) {
            golf.stroke++;
            if (golf.stroke === 4) {
                golf.state = 'failure_screen';
                golf.animTimer = 0;
            } else {
                golf.ball.x = golf.prevBallPos.x;
                golf.ball.y = golf.prevBallPos.y;
                golf.ball.vx = 0;
                golf.ball.vy = 0;
                golf.state = 'aiming';
            }
        }
    }
}

function handleGolfInput(key) {
    const golf = minigameState.golf;
    if (!golf) return;
    
    if (key === ' ' || key === 'Spacebar') {
        if (golf.state === 'aiming') {
            golf.state = 'power_windup';
            golf.power = 0;
            golf.powerDirection = 1;
        } else if (golf.state === 'power_windup') {
            const distance = 10 + golf.power * 1090;
            const speed = distance * 0.02;
            golf.ball.vx = Math.cos(golf.aimAngle) * speed;
            golf.ball.vy = Math.sin(golf.aimAngle) * speed;
            golf.prevBallPos.x = golf.ball.x;
            golf.prevBallPos.y = golf.ball.y;
            golf.state = 'moving';
        }
    }
}

function handleGolfMouseDown(e) {
    const golf = minigameState.golf;
    if (golf && golf.state === 'aiming') {
        golf.isDragging = true;
        updateGolfAim(e);
    }
}

function handleGolfMouseMove(e) {
    const golf = minigameState.golf;
    if (golf && golf.state === 'aiming' && golf.isDragging) {
        updateGolfAim(e);
    }
}

function handleGolfMouseUp(e) {
    const golf = minigameState.golf;
    if (golf) {
        golf.isDragging = false;
    }
}

function updateGolfAim(e) {
    const pos = getCanvasPointerPos(e);
    const mx = pos.x;
    const my = pos.y;
    
    const greenX = isMobileMode ? Math.floor((canvas.width - 400) / 2) : 200;
    const greenY = isMobileMode ? 220 : 130;

    const bx = greenX + (minigameState.golf.ball.x / 1254) * 400;
    const by = greenY + (minigameState.golf.ball.y / 1254) * 400;
    
    minigameState.golf.aimAngle = Math.atan2(my - by, mx - bx);
}
